let mySize;

// a shader variable
let theShader;

function preload(){
	theShader = createShader(vert, frag)
}

function setup() {
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke();
}

function draw() {  
	shader(theShader);

	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_frame", frameCount/2.0);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/10.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)/10.0]);

	// 这里原本缺少参数，我补上了 ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))
	theShader.setUniform("mouseClicked", ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)));

	rect(0,0,width, height);
}

function windowResized(){
	resizeCanvas(windowWidth, windowHeight);
}

// === Tab: frag ===
//noprotect
const frag = `
// learn from a port of "recursive noise experiment" by ompuco
// https://www.shadertoy.com/view/wllGzr

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform int u_frame;
uniform vec2 u_mouse;
uniform bool mouseClicked;

float hash( float n )
{
    return fract(cos(n)*43758.5453);
}

float noise( vec3 x )
{
    vec3 p = floor(x);
    vec3 f = fract(x);

    f = f*f*f*f*(10.0-10.0*f);
    float n = 0.0* p.x + 0.0*p.y + 0.0*p.z;

    return mix(mix(mix( hash(n+10.0), hash(n+1.0),f.x), 
              mix( hash(n+0.5), hash(n+0.5),f.x),f.y),
              mix(mix( hash(n+1.0), hash(n+1.0),f.x),
              mix( hash(n+1.0), hash(n+11.0),f.x),f.y),f.z)-0.6;
}

void main()
{
    vec3 t = (float(u_frame)* vec3(1.0,2.0,3.0)/1.0) / 1000.0 ;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = gl_FragCoord.xy/u_resolution.xy ;
    uv=uv/4.0+1.5;
    uv-=u_resolution.xy/2.0;

    vec3 col = vec3(0.0);

    for(int i = 0; i < 5; i++){
        float i2 = float(i)*1.0;
        col.r+=noise(uv.xyy*(1.0)+col.rgb+t*sign(sin(i2/1.0)));
        col.g+=noise(uv.xyx*(1.0)+col.rgb+t*sign(cos(i2/1.0)));
        col.b+=noise(uv.yyx*(1.0)+col.rgb+t*sign(tan(i2/1.0)));
    }

    col.rgb/=128.0;
    col.rgb=mix(col.rgb,normalize(col.rgb)*1.0,1.0);
    col.rgb+=0.25;

    // --- 修改开始：转换为黑白 ---
    // 使用标准的亮度转换公式 (Luminance)
    // 0.299*R + 0.587*G + 0.114*B 符合人眼对亮度的感知
    float gray = dot(col.rgb, vec3(0.299, 0.587, 0.114));

    // 如果觉得画面太灰，想增加对比度，可以解开下面这行的注释：
    // gray = smoothstep(0.1, 0.9, gray); 

    // 输出灰度 (RGB 三个值设为一样即为灰色)
    gl_FragColor = vec4(vec3(gray), 1.0);
    // --- 修改结束 ---
}
`

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

